injection.command:
config=$(vtysh -c "show running-config") || exit $?
  present=$(printf '%s\n' "$config" | awk '$1 == "network" && $2 == "192.168.216.0/24" {n++} END {print n+0}') || exit $?
  case "$present" in
    0) echo 'Advertisement already absent' ;;
    1) vtysh -c "configure terminal" -c "router ospf" -c "no network 192.168.216.0/24 area 1" -c "end" ;;
    *) echo 'Unexpected network statement count' >&2; exit 2 ;;
  esac

current=$(awk '$1 == "router" && $2 == "eigrp" {print $3}' /etc/frr/frr.conf) || exit $?
  case "$current" in
    101) echo 'EIGRP AS already 101' ;;
    100) sed -i 's/^router eigrp 100$/router eigrp 101/' /etc/frr/frr.conf && /etc/init.d/frr restart && vtysh -b ;;
    *) echo 'Unexpected EIGRP configuration' >&2; exit 2 ;;
  esac

